import { test, expect } from '@playwright/test';

test.describe('Modal Form Submission', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
    await page.getByRole('button', { name: /open modal/i }).click(); // Open the modal
  });

  test('should fill the form and submit successfully', async ({ page }) => {
    await page.getByLabel('Name').fill('John Doe');
    await page.getByLabel('Email').fill('john.doe@example.com');
    await page.getByRole('button', { name: /submit/i }).click();

    const successMessage = await page.getByText(/submission successful/i);
    await expect(successMessage).toBeVisible();
  });

  test('should show validation error for empty fields', async ({ page }) => {
    await page.getByRole('button', { name: /submit/i }).click();

    const errorMessage = await page.getByText(/please fill out this field/i);
    await expect(errorMessage).toBeVisible();
  });
});
